"""Generate a tiny valid workbook mirroring the real sheet structure."""
import os

import openpyxl

HERE = os.path.dirname(__file__)


def build(path=None):
    path = path or os.path.join(HERE, "mini.xlsx")
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "경매전체데이터"
    headers = ["경매일", "차군", "제작사", "차종", "모델명", "차명", "연식", "최초등록일",
               "차량경력", "원동기형식", "배기량", "연료", "평가등급", "사고'A' 상세",
               "색상", "주행거리", "변속기", "차량옵션", "재출품횟수", "경매팀사고내용",
               "시작가(만원)", "희망가(만원)", "낙찰가", "내수수출구분", "경매상태",
               "부재자 건수", "XX 교환 ", "W 판금,용접,꺾임", "기능평가상세"]
    ws.append(headers)
    rows = [
        ["2026-07-15", "중/대형", "현대", "그랜저", "그랜저HG", "현대 그랜저HG 300", 2014,
         "2014-04-24", "자가용", "G6DG", 2999, "가솔린", "AD", "골격판금", "기타", 174102,
         "오토", "옵션", 0, "", 170, 190, 375, "수출", "낙찰", 4, "프론트펜더(좌)", "리어팬더(좌)", "엔진"],
        ["2026-07-15", "경차", "기아", "모닝", "올 뉴모닝", "기아 올 뉴모닝 디럭스", 2012,
         "2012-06-18", "자가용", "G3LA", 998, "가솔린", "AB", "무사고", "흰색", 96632,
         "오토", "", 0, "", 90, 120, 225, "수출", "낙찰", 5, 0, 0, "엔진"],
        ["2026-07-15", "중/대형", "현대", "쏘나타", "쏘나타 디 엣지", "현대 쏘나타 디 엣지", 2024,
         "2023-07-24", "렌터카", "L4NB", 1999, "LPG", "AA", "무사고", "흰색", 92566,
         "오토", "스마트키", 0, "", 1650, 1700, 1705, "수출", "낙찰", 3, 0, 0, "조향"],
        # 낙찰가 누락 → 제외 대상
        ["2026-07-15", "경차", "기아", "레이", "레이", "기아 레이 프레스티지", 2020,
         "2020-01-01", "자가용", "G3", 998, "가솔린", "AA", "무사고", "흰색", 50000,
         "오토", "", 0, "", 80, 100, None, "내수", "유찰", 0, 0, 0, "엔진"],
    ]
    for r in rows:
        ws.append(r)

    # Reference price sheet with header on row 5 (rows 1-4 are titles).
    ps = wb.create_sheet("시세표_테이블")
    for _ in range(4):
        ps.append([])
    ps.append(["차명 (*)", "연료", "내수/수출", "2012", "2014", "2024"])
    ps.append(["그랜저HG 300", "가솔린", "수출", None, 380, None])
    ps.append(["올 뉴모닝 디럭스", "가솔린", "수출", 230, None, None])

    wb.save(path)
    return path


if __name__ == "__main__":
    print(build())
